package com.lacoste.verification;
import android.content.Context;import org.json.*;
public final class VerificationProcessor { private VerificationProcessor(){} public static void process(Context c,String t){try{JSONObject p=VerificationStore.pending(c);if(p==null)return;if(System.currentTimeMillis()>p.optLong("deadline",0)){VerificationStore.clearPending(c);return;}String prov=SmsParser.provider(t);if(prov==null)return;String wanted=p.optString("provider","all");if(!"all".equals(wanted)&&!wanted.equals(prov))return;String id=SmsParser.id(t);double v=SmsParser.value(t);if(!id.equalsIgnoreCase(p.optString("paymentId",""))||Math.abs(v-p.optDouble("value",-999))>0.001)return;new Thread(()->{try{VerificationApi.verify(c,p.optString("pedidoId"),id);VerificationStore.clearPending(c);}catch(Exception ignored){}}).start();}catch(Exception ignored){}}}
